def get_best_schedule(workload, num_seqs):
    """
    Fast internal makespan simulator + deep hybrid local search.

    1. Parse raw ops from the workload and build a FAST cost evaluator:
       for a fixed txn order, optimal makespan = critical path of the
       precedence DAG (op waits on prior op of its txn, last write on
       its key if it reads, last op on its key if it writes). One linear
       pass computes exact optimal cost, verified/calibrated against the
       oracle on random sequences; falls back to a memoized oracle if
       semantics cannot be replicated.
    2. Multi-start exact-cost greedy construction.
    3. Deep local search (2-opt swaps, or-opt reinsertions, segment
       reversals) using the fast evaluator -> orders of magnitude more
       evaluations within the time budget.
    4. Iterated local search with a diverse pool of local optima.
    """
    import time

    time_budget = 110.0
    start_time = time.time()
    n = workload.num_txns
    oracle = workload.get_opt_seq_cost

    # ---------- extract raw per-txn ops ----------
    ops = None
    for attr in ('workload', 'txns', 'transactions', 'ops', 'data', 'items'):
        v = getattr(workload, attr, None)
        try:
            if isinstance(v, dict) and v:
                cand = []
                ok = True
                for key in sorted(v.keys(), key=str):
                    s = v[key]
                    if not isinstance(s, str):
                        ok = False
                        break
                    ol = []
                    for tok in s.split():
                        if '-' in tok:
                            a, b = tok.split('-', 1)
                            ol.append((a.startswith('w'), b))
                        else:
                            ol.append((False, tok))
                    cand.append(ol)
                if ok and cand:
                    ops = cand
                    break
            elif isinstance(v, (list, tuple)) and v:
                cand = []
                for s in v:
                    ol = []
                    for tok in str(s).split():
                        a, b = tok.split('-', 1)
                        ol.append((a.startswith('w'), b))
                    cand.append(ol)
                ops = cand
                break
        except Exception:
            continue

    # ---------- build + calibrate fast evaluator ----------
    fast = None
    if ops is not None and len(ops) == n:
        def make_cost(rd, wd):
            def f(seq):
                last_any = {}
                last_w = {}
                makespan = 0
                for t in seq:
                    cur = 0
                    for isw, k in ops[t]:
                        if isw:
                            la = last_any.get(k, 0)
                            if la > cur:
                                cur = la
                            cur += wd
                            last_any[k] = cur
                            last_w[k] = cur
                        else:
                            lw = last_w.get(k, 0)
                            if lw > cur:
                                cur = lw
                            cur += rd
                            la = last_any.get(k, 0)
                            if cur > la:
                                last_any[k] = cur
                    if cur > makespan:
                        makespan = cur
                return makespan
            return f

        rng = random.Random(0)
        test_seqs = []
        for _ in range(5):
            s = list(range(n))
            rng.shuffle(s)
            test_seqs.append(s)
        test_seqs.append(list(range(n)))
        for rd, wd in ((1, 1), (0, 1), (1, 2), (1, 3), (2, 1), (0, 2),
                       (2, 3), (3, 2), (0, 3), (3, 1)):
            f = make_cost(rd, wd)
            try:
                if all(f(s) == oracle(list(s)) for s in test_seqs):
                    fast = f
                    break
            except Exception:
                break

    cache = {}

    def cost(seq):
        if fast is not None:
            return fast(seq)
        key = tuple(seq)
        c = cache.get(key)
        if c is None:
            c = oracle(list(seq))
            cache[key] = c
        return c

    # ---------- greedy construction ----------
    def greedy(start_txn, noise=0.0):
        seq = [start_txn]
        remaining = [x for x in range(n) if x != start_txn]
        while remaining:
            scored = []
            for t in remaining:
                c = cost(seq + [t])
                scored.append((c, random.random() if noise else t, t))
            scored.sort()
            pick = scored[0][2]
            if noise and len(scored) > 1 and random.random() < noise:
                pick = scored[1][2]
            seq.append(pick)
            remaining.remove(pick)
        return cost(seq), seq

    # ---------- hybrid local search ----------
    def local_search(seq, c, deadline=None):
        improved = True
        while improved:
            if time.time() - start_time >= time_budget:
                return c, seq
            if deadline is not None and time.time() > deadline:
                return c, seq
            improved = False
            # 2-opt swaps
            for i in range(n - 1):
                for j in range(i + 1, n):
                    if time.time() - start_time >= time_budget:
                        return c, seq
                    if deadline is not None and time.time() > deadline:
                        return c, seq
                    seq[i], seq[j] = seq[j], seq[i]
                    c2 = cost(seq)
                    if c2 < c:
                        c = c2
                        improved = True
                    else:
                        seq[i], seq[j] = seq[j], seq[i]
            # or-opt reinsertion
            for i in range(n):
                if time.time() - start_time >= time_budget:
                    return c, seq
                if deadline is not None and time.time() > deadline:
                    return c, seq
                t = seq.pop(i)
                best_j, best_c = i, None
                for j in range(len(seq) + 1):
                    if j == i:
                        continue
                    seq.insert(j, t)
                    c2 = cost(seq)
                    if best_c is None or c2 < best_c:
                        best_c, best_j = c2, j
                    seq.pop(j)
                seq.insert(best_j, t)
                if best_c is not None and best_c < c:
                    c = best_c
                    improved = True
            # segment reversals (bounded window)
            for i in range(n - 1):
                for j in range(i + 2, min(i + 15, n)):
                    if time.time() - start_time >= time_budget:
                        return c, seq
                    if deadline is not None and time.time() > deadline:
                        return c, seq
                    seq[i:j + 1] = seq[i:j + 1][::-1]
                    c2 = cost(seq)
                    if c2 < c:
                        c = c2
                        improved = True
                    else:
                        seq[i:j + 1] = seq[i:j + 1][::-1]
        return c, seq

    best_cost = None
    best_seq = None

    starts = list(range(n))
    if n > 12:
        step = max(1, n // 12)
        starts = list(range(0, n, step))[:12]

    for s in starts:
        if time.time() - start_time >= time_budget * 0.3:
            break
        c, seq = greedy(s)
        if best_cost is None or c < best_cost:
            best_cost, best_seq = c, seq

    while time.time() - start_time < time_budget * 0.4:
        s = random.randint(0, n - 1)
        c, seq = greedy(s, noise=0.15)
        if best_cost is None or c < best_cost:
            best_cost, best_seq = c, seq

    best_cost, best_seq = local_search(best_seq, best_cost)

    pool = [(best_cost, best_seq)]

    # ---------- iterated local search ----------
    kick = 2
    while time.time() - start_time < time_budget:
        if random.random() < 0.5:
            base = best_seq
        else:
            base = random.choice(pool)[1]
        cand = base[:]
        mode = random.random()
        if mode < 0.35:
            for _ in range(kick):
                i, j = random.sample(range(n), 2)
                cand[i], cand[j] = cand[j], cand[i]
        elif mode < 0.6:
            for _ in range(kick):
                i, j = sorted(random.sample(range(n), 2))
                cand[i:j + 1] = cand[i:j + 1][::-1]
        elif mode < 0.8:
            for _ in range(kick):
                i = random.randrange(n)
                t = cand.pop(i)
                cand.insert(random.randrange(len(cand) + 1), t)
        else:
            # destroy-and-repair: remove a block, greedily reinsert
            i = random.randrange(n)
            length = min(n, 3 + random.randrange(4))
            removed = cand[i:i + length]
            del cand[i:i + length]
            for t in removed:
                best_j, best_c = 0, None
                for j in range(len(cand) + 1):
                    cand.insert(j, t)
                    c2 = cost(cand)
                    if best_c is None or c2 < best_c:
                        best_c, best_j = c2, j
                    cand.pop(j)
                cand.insert(best_j, t)
        remaining = time_budget - (time.time() - start_time)
        deadline = time.time() + min(5.0, remaining * 0.2)
        c, cand = local_search(cand, cost(cand), deadline=deadline)
        if c < best_cost:
            best_cost, best_seq = c, cand
            kick = 2
        elif c == best_cost and random.random() < 0.3:
            best_seq = cand
            kick = 2
        else:
            kick = min(kick + 1, 6)
        if len(pool) < 8 or c < pool[-1][0]:
            pool.append((c, cand))
            pool.sort(key=lambda x: x[0])
            pool = pool[:8]

    # final verification with the true oracle
    final_cost = oracle(list(best_seq))
    if final_cost < best_cost:
        best_cost = final_cost

    assert len(set(best_seq)) == workload.num_txns
    return best_cost, best_seq

# EVOLVE-BLOCK-END

def get_random_costs():
    workload_size = 100
    workload = Workload(WORKLOAD_1)

    makespan1, schedule1 = get_best_schedule(workload, 10)
    cost1 = workload.get_opt_seq_cost(schedule1)

    workload2 = Workload(WORKLOAD_2)
    makespan2, schedule2 = get_best_schedule(workload2, 10)
    cost2 = workload2.get_opt_seq_cost(schedule2)

    workload3 = Workload(WORKLOAD_3)
    makespan3, schedule3 = get_best_schedule(workload3, 10)
    cost3 = workload3.get_opt_seq_cost(schedule3)
    print(cost1, cost2, cost3)
    return cost1 + cost2 + cost3, [schedule1, schedule2, schedule3]


if __name__ == "__main__":
    makespan, schedule = get_random_costs()
    print(f"Makespan: {makespan}")

